<?php
require_once __DIR__.'/../../includes/user-check.php';$flow=$_SESSION['diagnosis_flow']??null;
if(!$flow||empty($flow['questions'])){flash('error','Mulai diagnosis baru dengan memilih motor.');redirect('/user/diagnosis/index.php');}
$step=(int)$flow['step'];$total=count($flow['questions']);if($step<0||$step>=$total)redirect('/user/diagnosis/selesai.php');
$q=$pdo->prepare('SELECT kode,nama,deskripsi FROM gejala WHERE id=?');$q->execute([(int)$flow['questions'][$step]]);$question=$q->fetch();if(!$question){unset($_SESSION['diagnosis_flow']);flash('error','Data gejala berubah. Silakan mulai kembali.');redirect('/user/diagnosis/index.php');}
$progress=(int)floor(($step/$total)*100);$page_title='Pertanyaan Diagnosis';require __DIR__.'/../../includes/header.php';require __DIR__.'/../../includes/flash-message.php';
?>
<section class="app-content-header"><div class="container-fluid"><h3>Diagnosis Motor</h3><p class="text-body-secondary mb-2">Pertanyaan <?= $step+1 ?> dari <?= $total ?></p><div class="progress" role="progressbar" aria-label="Progress diagnosis" aria-valuenow="<?= $progress ?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:<?= $progress ?>%"><?= $progress ?>%</div></div></div></section>
<section class="content"><div class="container-fluid"><div class="card"><div class="card-body p-4"><div class="small text-body-secondary mb-2"><?= e($question['kode']) ?></div><h2 class="h4 mb-3"><?= e($question['nama']) ?></h2><?php if($question['deskripsi']): ?><p><?= e($question['deskripsi']) ?></p><?php endif ?><form method="post" action="proses.php"><?= csrf_field() ?><input type="hidden" name="action" value="answer"><div class="d-flex flex-wrap gap-2"><button class="btn btn-success btn-lg px-4" name="jawaban" value="YA" type="submit"><i class="bi bi-check-circle me-1"></i>YA</button><button class="btn btn-outline-secondary btn-lg px-4" name="jawaban" value="TIDAK" type="submit"><i class="bi bi-x-circle me-1"></i>TIDAK</button></div></form><div class="d-flex justify-content-between mt-4"><form method="post" action="proses.php"><?= csrf_field() ?><input type="hidden" name="action" value="back"><button class="btn btn-link px-0" type="submit" <?= $step===0?'disabled':'' ?>><i class="bi bi-arrow-left me-1"></i>Kembali</button></form><form method="post" action="proses.php" onsubmit="return confirm('Batalkan diagnosis ini? Jawaban yang belum dikirim tidak akan disimpan.');"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><button class="btn btn-link text-danger px-0" type="submit">Batalkan</button></form></div></div></div></div></section><?php require __DIR__.'/../../includes/footer.php'; ?>
